using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ConstellationBeadsOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/ConstellationBeadsOmenData")]
public class ConstellationBeadsOmenData : OmenData
{
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.ConstellationBeadsOmenAction = delegate
		{
			if (counter == TriggerAmount - 2)
			{
				omenInstance.PlayBlinkingFeedback();
			}
			else if (counter == TriggerAmount - 1)
			{
				omenInstance.StopBlinkingFeedback();
				omenInstance.EnqueueOmenFeedbackAndPlay();
			}
			ActivateOmen();
			omenInstance.UpdateOmenCounter();
		};
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
		}
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.ConstellationBeadsOmenAction = null;
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
		}
	}
}
